function drawPachirisuSquirrel(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 6.0;
  const tailSwayY = Math.cos(tailLag) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi sóc khổng lồ
  const tx = 18 + tailSwayX;
  const ty = by - 10 + tailSwayY;
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.ellipse(tx + 2, ty - 2, 16, 28, 0, 0, Math.PI * 2); ctx.fill();
  // Gai đuôi
  ctx.beginPath();
  ctx.moveTo(tx + 14, ty - 20); ctx.lineTo(tx + 24, ty - 38); ctx.lineTo(tx + 6, ty - 24); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(tx + 16, ty - 6); ctx.lineTo(tx + 28, ty - 18); ctx.lineTo(tx + 10, ty - 10); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(tx + 14, ty + 10); ctx.lineTo(tx + 24, ty + 4); ctx.lineTo(tx + 8, ty + 6); ctx.fill();
  // Bụng đuôi trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(tx - 6, ty, 12, 24, 0, 0, Math.PI * 2); ctx.fill();

  // Thân trắng & chân
  ctx.beginPath(); ctx.ellipse(-6, by + 16, 16 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-15, by + 29, 7, 11, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(3, by + 29, 7, 11, 4); ctx.fill();

  // Đầu trắng
  ctx.beginPath(); ctx.ellipse(-6, by - 6, 20 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai trắng chóp xanh
  ctx.beginPath(); ctx.moveTo(-19, by - 14); ctx.lineTo(-24, by - 34); ctx.lineTo(-13, by - 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(3, by - 15); ctx.lineTo(8, by - 34); ctx.lineTo(11, by - 18); ctx.fill();
  ctx.fillStyle = '#38bdf8';
  ctx.beginPath(); ctx.moveTo(-21, by - 24); ctx.lineTo(-24, by - 34); ctx.lineTo(-16, by - 26); ctx.fill();
  ctx.beginPath(); ctx.moveTo(5, by - 25); ctx.lineTo(8, by - 34); ctx.lineTo(10, by - 26); ctx.fill();
  // Sọc trán
  ctx.beginPath(); ctx.moveTo(-6, by - 22); ctx.lineTo(-10, by - 10); ctx.lineTo(-2, by - 10); ctx.fill();

  // Má vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.arc(-18, by + 1, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(6, by + 1, 6, 0, Math.PI * 2); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.ellipse(-12, by - 6, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(0, by - 6, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-13, by - 9, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(-1, by - 9, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng & răng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(-6, by + 7); ctx.lineTo(-10, by + 2); ctx.lineTo(-2, by + 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-7, by + 2, 3, 3);

  // Tay nhỏ
  ctx.beginPath(); ctx.arc(-10, by + 12, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-2, by + 12, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
